using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

// --- 1. GetTypeInfo<T>(): strongly-typed metadata retrieval ---
var options = new JsonSerializerOptions(JsonSerializerDefaults.Web);

JsonTypeInfo<Person> typeInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"GetTypeInfo<Person> returned type: {typeInfo.Type.Name}");

string json = JsonSerializer.Serialize(new Person("Alice", 42), typeInfo);
Console.WriteLine($"Serialized: {json}");

// --- 2. TryGetTypeInfo<T>(): check-without-throwing ---
// With the default (reflection-based) resolver, Person resolves fine:
if (options.TryGetTypeInfo<Person>(out JsonTypeInfo<Person>? personInfo))
    Console.WriteLine($"TryGet succeeded for {personInfo!.Type.Name}");
else
    Console.WriteLine("TryGet failed for Person (unexpected)");

// Build options that use a source-gen context which only knows about int,
// so looking up Person will legitimately fail without throwing.
var limited = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
        .WithAddedModifier(ti =>
        {
            // Only allow metadata for System.Int32
            if (ti.Type != typeof(int))
                throw new NotSupportedException();
        })
};
// Pre-populate the int metadata so the resolver is "locked in"
_ = limited.GetTypeInfo<int>();

if (limited.TryGetTypeInfo<Person>(out JsonTypeInfo<Person>? missing))
    Console.WriteLine($"TryGet succeeded for Person: {missing!.Type.Name}");
else
    Console.WriteLine("TryGet correctly reported Person metadata unavailable");

public record Person(string Name, int Age);

